/bin/zsh -c "python3 -c 'from fractions import Fraction

def factor(n):
    fs={}
    p=2
    while p*p<=n:
        while n%p==0:
            fs[p]=fs.get(p,0)+1
            n//=p
        p+=1
    if n>1: fs[n]=1
    return fs

def local_density(q,l):
    z=Fraction(1)
    for p,t in factor(q).items():
        if t>=2 and l%(p*p)==0: return Fraction(0)
        z/=1-Fraction(1,p*p)
        if t==1 and l%p==0: z*=1-Fraction(1,p)
    return z/q

def L(r):
    z=Fraction(1)
    for p,t in factor(r).items():
        if t>=3: return Fraction(0)
        z*=Fraction(p**t-p**(t-1),(p*p-1)**2)
    return z

for q in range(1,257):
    lhs=q*sum((local_density(q,l)**2 for l in range(1,q+1)),Fraction(0))
    rhs=sum((L(r) for r in range(1,q+1) if q%r==0),Fraction(0))
    assert lhs==rhs,(q,lhs,rhs)
for r in range(1,4097):
    fs=factor(r)
    if any(t>2 for t in fs.values()): continue
    a=b=1
    for p,t in fs.items():
        if t==1: a*=p
        else: b*=p
    assert L(r)<=Fraction(1,a**3*b**2)
for p in (2,3,5,7,11,13):
    for n in range(1,2*p*p+1):
        cp=p*int(n%p==0)-1
        cp2=p*p*int(n%(p*p)==0)-p*int(n%p==0)
        z=(1-Fraction(1,p*p))**2*(1+Fraction(cp+cp2,(p*p-1)**2))
        target=1-Fraction(1 if n%(p*p)==0 else 2,p*p)
        assert z==target
print(\"Exact rational checks passed: second moments for q=1..256; coefficient bounds for r=1..4096; Ramanujan local factors for six primes, including p=2.\")'"

